"""E153 prediction-only report, preserving fixed-kernel attribution."""
import shutil
from pathlib import Path
from .fixed_uniform_learning import ROOT
from .abstaining_task_value_gate import read,save,fingerprint

def run():
    s=read(ROOT/'summary.json');assert read(ROOT/'verification.json')['all_predictions_exact'];m=s['metrics'];ratio=(m['ensemble']['all']['position_rmse_mm']/m['reference']['all']['position_rmse_mm'])**2;lines=['# E153: fixed-uniform learned history weights','','The uniform32 baseline remains the strongest nonprivileged task reference so far. This study preserves its.98recency and zero-centered1e-6ridge exactly, learning only mass-normalized relative weights over32 measured transitions. No measured-calibration prior term or prior-derived feature is used. The8-feature Transformer and explicit weighted analytical solve are unchanged from the earlier weighting architecture.','', 'Same6706 observed transitions,96 fitting placements, four ancestry-family folds, three fixed seeds and placement-balanced training. The whole research/data-collection pipeline is adaptive development, not a nested final-test estimate. No task-success labels, privileged Jacobians or future queries enter network features.','', '| Estimator | All position RMSE (mm) | Six joints | Seven joints | Scaled rotation RMSE (mm) |','|---|---:|---:|---:|---:|']
    for k,v in m.items():lines.append(f"| {k} | {v['all']['position_rmse_mm']:.4f} | {v['6']['position_rmse_mm']:.4f} | {v['7']['position_rmse_mm']:.4f} | {v['all']['rotation_rmse_mm']:.4f} |")
    lines+=['',f"Fixed all-three ensemble position MSE improves by {(1-ratio)*100:.1f}%. Every individual seed improves overall and both joint counts improve. Prediction screen passes: {s['qualifies_for_control']}. This is a smaller prediction gain than the calibration-prior model, but preserves the stronger task baseline structure. E154 must establish whether it improves complete tasks; no task gain is claimed here.",'', 'Independent NumPy reference solves, uniform initialization, exact prediction reproduction, fixed ridge/forgetting, mass normalization, family exclusion and source hashes were verified. E120 remains unchanged; reserved fresh placements remain unopened.','', 'Source successes/failures: [E144 gallery](../ease_history_estimator_control_v1/videos/index.html). Those are context videos, not E153 controller demonstrations. E154 saves actual learned fixed-kernel trajectories separately.',''];(ROOT/'report.md').write_text('\n'.join(lines));report=Path(__file__).with_name('TECHNICAL_REPORT.md');text=report.read_text(encoding='utf-8');assert '## E153:' not in text;report.write_text(text+'\n## E153: learned weights with fixed uniform kernel\n\nEnsemble position RMSE0.388mm vs uniform0.415,12.6% lowerMSE; all seeds and joint counts improve. Kernel and ridge exactly preserved, no calibration prior. Prediction only; complete control is E154. Report: `outputs/ease_fixed_uniform_learning_v1/report.md`.\n',encoding='utf-8')
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    fig,ax=plt.subplots(figsize=(7,4));ax.bar(['Fixed uniform','Learned relative weights'],[m['reference']['all']['position_rmse_mm'],m['ensemble']['all']['position_rmse_mm']]);ax.set_ylabel('Position RMSE (mm)');ax.set_title('E153 | same kernel and ridge | prediction only');fig.tight_layout();fig.savefig(ROOT/'comparison.png',dpi=150);plt.close(fig);shutil.copy2(__file__,ROOT/'source'/Path(__file__).name);save(ROOT/'artifact_hashes.json',{str(p.relative_to(ROOT)):fingerprint(p) for p in ROOT.rglob('*') if p.is_file() and p.name!='artifact_hashes.json'});print('E153 report archived',flush=True)

if __name__=='__main__':run()
